// AI-powered metadata enhancement
const inputData = $input.first().json;
const extractedMetadata = inputData.extracted || {};
const userMetadata = inputData.metadata || {};

// Enhance with AI analysis
const enhancedMetadata = {
  ...userMetadata,
  ...extractedMetadata,

  // AI-enhanced fields
  mood: extractedMetadata.mood || inferMoodFromGenre(userMetadata.genre),
  energy: extractedMetadata.energy || inferEnergyFromBPM(userMetadata.bpm),
  danceability: calculateDanceability(userMetadata.bpm, userMetadata.genre),
  valence: inferValenceFromMood(extractedMetadata.mood || userMetadata.mood),

  // Professional enhancements
  distribution_ready: checkDistributionReadiness(userMetadata),
  professional_complete: checkProfessionalCompleteness(userMetadata),

  // Timestamp
  enhanced_at: new Date().toISOString()
};

function inferMoodFromGenre(genre) {
  const moodMap = {
    'electronic': 'energetic',
    'hip-hop': 'confident',
    'jazz': 'sophisticated',
    'rock': 'powerful',
    'pop': 'uplifting',
    'classical': 'elegant'
  };
  return moodMap[genre?.toLowerCase()] || 'neutral';
}

function inferEnergyFromBPM(bpm) {
  if (!bpm) return 5;
  if (bpm < 80) return 2;
  if (bpm < 100) return 4;
  if (bpm < 120) return 6;
  if (bpm < 140) return 8;
  return 9;
}

function calculateDanceability(bpm, genre) {
  const danceGenres = ['electronic', 'house', 'techno', 'disco', 'funk'];
  const isDanceGenre = danceGenres.includes(genre?.toLowerCase());
  const bpmFactor = bpm ? Math.min(bpm / 128, 1) : 0.5;
  return isDanceGenre ? Math.min(bpmFactor + 0.3, 1) : bpmFactor;
}

function inferValenceFromMood(mood) {
  const valenceMap = {
    'uplifting': 0.8,
    'energetic': 0.7,
    'happy': 0.9,
    'neutral': 0.5,
    'melancholic': 0.2,
    'dark': 0.1,
    'aggressive': 0.3
  };
  return valenceMap[mood?.toLowerCase()] || 0.5;
}

function checkDistributionReadiness(metadata) {
  const required = ['title', 'artist', 'album', 'releaseYear', 'genre'];
  return required.every(field => metadata[field]);
}

function checkProfessionalCompleteness(metadata) {
  const professional = ['title', 'artist', 'genre', 'bpm', 'producer', 'recordLabel'];
  return professional.filter(field => metadata[field]).length >= 4;
}

return enhancedMetadata;
